-- 011_bd_destination_guides.sql
-- Round 115, Phase G (master prompt item 20 -- "Bangladesh Travel Intelligence").
--
-- Content below was compiled via web research (Wikipedia/Wikivoyage citations
-- per row, see the `sources` column) on 2026-09-20, not generated from memory --
-- Rule 3 (never fabricate real-world data). Several details that could not be
-- independently confirmed (exact flight durations, Saint Martin's current access
-- status, Sajek's specific permit-convoy timing, Kuakata's post-2022-bridge route,
-- Paharpur's district) are deliberately hedged or flagged in the text below rather
-- than stated as fact -- see frontend/bd-guide.php's own disclosure banner, which
-- tells the visitor this is curated/researched content, not a live feed, and to
-- verify time-sensitive details (permits, island access) before traveling.
CREATE TABLE IF NOT EXISTS `tbl_bd_destination_guides` (
  `id` INT(11) NOT NULL AUTO_INCREMENT,
  `slug` VARCHAR(60) NOT NULL,
  `name` VARCHAR(120) NOT NULL,
  `known_for` TEXT NOT NULL,
  `best_time` TEXT NOT NULL,
  `how_to_get_there` TEXT NOT NULL,
  `practical_note` TEXT DEFAULT NULL,
  `sources` TEXT NOT NULL COMMENT 'pipe-separated source URLs, for attribution',
  `researched_at` DATE NOT NULL COMMENT 'when this content was compiled -- shown as a staleness signal, since access rules (e.g. Saint Martin''s) can change year to year',
  `created_at` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_bd_guide_slug` (`slug`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

INSERT IGNORE INTO tbl_bd_destination_guides (slug, name, known_for, best_time, how_to_get_there, practical_note, sources, researched_at) VALUES ('cox-bazar', 'Cox''s Bazar', 'World''s longest unbroken natural sea beach (about 120 km) | Bangladesh''s top beach resort town, known as the "Tourist Capital of Bangladesh." Nearby: Himchari National Park, Buddhist monasteries, Dulhazra Safari Park.', 'November-March (driest months). Avoid the June-August monsoon, which brings the heaviest rainfall.', 'Bus: about 9-12 hours from Dhaka via the N1 highway (traffic-dependent). Train: Cox''s Bazar Express, about 8 hours (line opened December 2023). Flight: Cox''s Bazar International Airport, served by Biman, US-Bangla, Novoair and Air Astra (exact flight duration not independently confirmed for this guide).', 'Like the wider Bay of Bengal coast, cyclone risk is elevated May-October.', 'https://en.wikipedia.org/wiki/Cox%27s_Bazar | https://en.wikipedia.org/wiki/Cox%27s_Bazar_Airport | https://en.wikipedia.org/wiki/Cox%27s_Bazar_Express', '2026-09-20');
INSERT IGNORE INTO tbl_bd_destination_guides (slug, name, known_for, best_time, how_to_get_there, practical_note, sources, researched_at) VALUES ('saint-martin', 'Saint Martin''s Island', 'Bangladesh''s only coral island, known for marine biodiversity (coral, seaweed, fish) and turtle nesting | a popular eco-tourism destination.', 'November-February is the established tourist season. Conditions and access in the March-July off-season (rising cyclone risk) can vary.', 'Boat/ship only -- no road or bridge connects the island. Services run from Cox''s Bazar and Teknaf during the open season.', 'IMPORTANT -- confirm current access before planning: this island has had recurring, year-to-year tourist access restrictions in recent years for environmental and border-security reasons (a nine-month restriction was reported starting February 2025). Check current status with a licensed operator before booking.', 'https://en.wikipedia.org/wiki/Saint_Martin%27s_Island', '2026-09-20');
INSERT IGNORE INTO tbl_bd_destination_guides (slug, name, known_for, best_time, how_to_get_there, practical_note, sources, researched_at) VALUES ('sajek-valley', 'Sajek Valley', 'Hill scenery at roughly 1,476-1,800 ft elevation, nicknamed the "Queen of Hills" | home to indigenous Chakma, Marma and Tripuri communities | known for cloud-covered ridge views.', 'Bangladesh''s general dry season (November-February) is the most comfortable time to visit hill areas | no destination-specific recommendation was found for Sajek itself.', 'No direct road to Sajek -- travel from Dhaka to Khagrachhari (or via Dighinala) by bus, then a local 4WD ("chander gari") for the final hill leg.', 'Sajek sits within the Chittagong Hill Tracts, where foreign visitors must apply for a permit through the Home Ministry in advance and register on arrival.', 'https://en.wikipedia.org/wiki/Sajek_Valley | https://en.wikivoyage.org/wiki/Chittagong_Hill_Tracts', '2026-09-20');
INSERT IGNORE INTO tbl_bd_destination_guides (slug, name, known_for, best_time, how_to_get_there, practical_note, sources, researched_at) VALUES ('bandarban', 'Bandarban', 'Home to the largest Buddhist temple/statue in Bangladesh (Balaghata) | waterfalls, Shangu River activities, and Bawm/Mru indigenous villages | a gateway to Nafakhum, Boga Lake and Thanchi.', 'Bangladesh''s general dry season (November-February) is the most comfortable time to visit | no destination-specific recommendation was found for Bandarban itself.', 'Bus is the realistic option -- roughly 8 hours from Dhaka (shorter from Chittagong or Cox''s Bazar). No rail or air service to Bandarban.', 'Since a 2015 policy, foreign tourists must apply to the Home Ministry a month in advance to visit Bandarban and other Chittagong Hill Tracts districts, and may be assigned a police escort (at the visitor''s cost) outside the main town.', 'https://en.wikipedia.org/wiki/Bandarban_District | https://en.wikivoyage.org/wiki/Chittagong_Hill_Tracts', '2026-09-20');
INSERT IGNORE INTO tbl_bd_destination_guides (slug, name, known_for, best_time, how_to_get_there, practical_note, sources, researched_at) VALUES ('rangamati', 'Rangamati', 'Kaptai Lake, the largest man-made lake in the country | the 335-ft Jhulonto (Hanging) Bridge | Kaptai National Park and Shuvolong waterfall | also a common jumping-off point for Sajek Valley.', 'Bangladesh''s general dry season (November-February) is the most comfortable time to visit | no destination-specific recommendation was found for Rangamati itself.', 'Direct bus service runs from Dhaka. Via Chittagong, the Paharika bus service covers the 77 km Chittagong-Rangamati leg in about 3 hours.', 'Same Chittagong Hill Tracts foreign-visitor permit requirement as Bandarban and Sajek (Home Ministry application in advance, registration on arrival).', 'https://en.wikipedia.org/wiki/Rangamati_District | https://en.wikivoyage.org/wiki/Rangamati', '2026-09-20');
INSERT IGNORE INTO tbl_bd_destination_guides (slug, name, known_for, best_time, how_to_get_there, practical_note, sources, researched_at) VALUES ('sylhet', 'Sylhet', 'Tea plantations and hill scenery | the Shah Jalal Dargah, a major Islamic pilgrimage shrine | Ratargul Swamp Forest, one of Bangladesh''s few freshwater swamp forests | haor wetlands with winter migratory birds.', 'November-February, the dry season with the clearest, most comfortable weather.', 'Road via the N2 highway. Train: multiple daily intercity services, e.g. Upaban Express, about 7 hours from Dhaka. Flight via Osmani International Airport (Biman, Novoair, US-Bangla, Air Astra).', NULL, 'https://en.wikipedia.org/wiki/Sylhet | https://en.wikipedia.org/wiki/Osmani_International_Airport | https://en.wikipedia.org/wiki/Upaban_Express', '2026-09-20');
INSERT IGNORE INTO tbl_bd_destination_guides (slug, name, known_for, best_time, how_to_get_there, practical_note, sources, researched_at) VALUES ('srimangal', 'Srimangal', 'Known as the "tea capital of Bangladesh" -- extensive tea gardens and the origin of the layered "Seven Color Tea" | Madhobpur Lake, Hum Hum waterfall, Baikka Beel wetland | near Lawachara National Park, home to Bangladesh''s largest population of the endangered western hoolock gibbon.', 'Bangladesh''s general dry season (November-February) is the most comfortable time to visit | no destination-specific recommendation was found for Srimangal itself.', 'Train: Srimangal is a stop on the Dhaka-Sylhet line (e.g. Upaban Express). Bus service also runs this route.', NULL, 'https://en.wikipedia.org/wiki/Sreemangal_Upazila | https://en.wikipedia.org/wiki/Upaban_Express | https://en.wikipedia.org/wiki/Lawachara_National_Park', '2026-09-20');
INSERT IGNORE INTO tbl_bd_destination_guides (slug, name, known_for, best_time, how_to_get_there, practical_note, sources, researched_at) VALUES ('kuakata', 'Kuakata', 'Called the "Daughter of the Sea" -- an 18 km beach uniquely offering unobstructed views of both sunrise and sunset over the Bay of Bengal | also a pilgrimage site for Hindu and Buddhist communities during certain festivals.', 'Bangladesh''s general dry season (November-February) is the most comfortable time to visit | as a Bay of Bengal beach, it likely shares the region''s May-October cyclone-season caution.', 'Historically via Dhaka to Barisal then onward by bus (with ferry crossings). Routing has likely changed since the 2022 Padma Bridge opening removed ferry dependency on the main southern corridor, but current post-bridge timing wasn''t independently confirmed for this guide -- check with a bus operator for the current fastest route.', 'Sources note environmental strain from overtourism (pollution, wildlife impact) at this beach.', 'https://en.wikipedia.org/wiki/Kuakata | https://en.wikipedia.org/wiki/Kuakata_Sea_Beach | https://en.wikivoyage.org/wiki/Kuakata | https://en.wikipedia.org/wiki/Padma_Bridge', '2026-09-20');
INSERT IGNORE INTO tbl_bd_destination_guides (slug, name, known_for, best_time, how_to_get_there, practical_note, sources, researched_at) VALUES ('sundarbans', 'Sundarbans', 'The world''s largest mangrove forest and a UNESCO World Heritage Site | core habitat of the endangered Bengal tiger | explored via boat-based wildlife safaris.', 'October-February (cool, dry season) is the clearly recommended time to visit.', 'No direct road or rail into the forest -- travel from Dhaka to Khulna (train, bus, or fly to Jashore then bus), then onward by hired boat/launch tour from Khulna, Mongla or Munshiganj-Satkhira. Independent boat travel requires a permit from the Divisional Forest Office in Khulna | most visitors book an organized multi-day safari package.', 'Tiger encounters pose very little risk to tourists on guided tours | the larger practical health risk is mosquito-borne disease, highest in the June-September wet season -- mosquito precautions are advised.', 'https://en.wikipedia.org/wiki/Sundarbans | https://en.wikivoyage.org/wiki/Sundarbans_(Bangladesh) | https://en.wikipedia.org/wiki/Khulna', '2026-09-20');
INSERT IGNORE INTO tbl_bd_destination_guides (slug, name, known_for, best_time, how_to_get_there, practical_note, sources, researched_at) VALUES ('rajshahi', 'Rajshahi', 'Home to the Varendra Research Museum, the oldest museum in Bangladesh | the shrine of Shah Makhdum Ruposh | riverside parks along the Padma | historically known for silk textiles | sometimes called the "Education City" for its universities.', 'November-February, avoiding the notably hot season (roughly early March to mid-July, with daytime temperatures of 32-36 degrees C).', 'Bus: about 5-6 hours from Dhaka. Train: four intercity services (Silk City Express, Padma Express, Dhumketu Express, Bonolota Express). Flight via Shah Makhdum Airport (Biman, Novoair, US-Bangla).', NULL, 'https://en.wikipedia.org/wiki/Rajshahi', '2026-09-20');
INSERT IGNORE INTO tbl_bd_destination_guides (slug, name, known_for, best_time, how_to_get_there, practical_note, sources, researched_at) VALUES ('paharpur', 'Paharpur (Somapura Mahavihara)', 'Somapura Mahavihara -- one of the best-known Buddhist monasteries in the Indian subcontinent and the largest known Buddhist vihara south of the Himalayas | a UNESCO World Heritage Site (1985) | an 11-hectare Pala-period monastic university site with notable terracotta plaques.', 'Bangladesh''s general dry season (November-February) is the most comfortable time to visit | no destination-specific recommendation was found.', 'Located near Jamalganj in Joypurhat District (sources vary slightly on Joypurhat vs. neighboring Naogaon district -- worth confirming locally). Joypurhat has rail connections to Dhaka | exact journey time and last-mile transport from the station to the site weren''t independently confirmed for this guide.', NULL, 'https://en.wikipedia.org/wiki/Somapura_Mahavihara | https://en.wikipedia.org/wiki/Naogaon_District | https://en.wikipedia.org/wiki/Jaipurhat_District', '2026-09-20');
INSERT IGNORE INTO tbl_bd_destination_guides (slug, name, known_for, best_time, how_to_get_there, practical_note, sources, researched_at) VALUES ('bagerhat', 'Bagerhat (Sixty Dome Mosque)', 'The Sixty Dome Mosque (Shat Gombuj Mosque) -- one of the most impressive Muslim monuments in South Asia and the largest surviving mosque from the Bengal Sultanate period, built in the 15th century by Khan Jahan Ali | part of the UNESCO-listed "Historic Mosque City of Bagerhat."', 'Bangladesh''s general dry season (November-February) is the most comfortable time to visit | no destination-specific recommendation was found.', 'Direct bus from Dhaka (about 3-5 hours), or fly to Jashore then bus onward. Rail service between Bagerhat and Khulna no longer operates | Khulna itself remains rail-connected to Dhaka if combining with a Sundarbans trip.', NULL, 'https://en.wikipedia.org/wiki/Bagerhat_District | https://en.wikipedia.org/wiki/Sixty_Dome_Mosque | https://en.wikipedia.org/wiki/Khulna', '2026-09-20');
